local lvgl = require("lvgl")
local voice = require("voice")
local ui = require("ui")
lvgl.init({ buffer_lines = 40 })
local scr = lvgl.create_screen()
scr:set_style({ bg_color = "#000000" })
ui.title(scr, "Spell")
local status = lvgl.label(scr, { text = "tap, then NATO-spell",
    align = "center", y = -40, text_color = "#ffffff" })
local btn = lvgl.button(scr, { text = "Spell", align = "bottom_mid", y = -16,
    w = 344, h = 104, bg_color = "#2F80ED", text_color = "#ffffff", radius = 12 })
btn:on("clicked", function()
    status:set_text("listening...")
    voice.spell(function(t)
        status:set_text(t and ("got: " .. t) or "nothing")
        print("SPELL_RESULT " .. tostring(t))
    end)
end)
scr:load()
